import{_ as l,l as i,o as e,c as n,v as t,p as s,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"预防与避免","description":"","frontmatter":{"title":"预防与避免","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/deadlock-prevent.md","filePath":"cs/deadlock-prevent.md","lastUpdated":1789023840000}'),h={name:"cs/deadlock-prevent.md"};function E(m,a,_,f,A,B){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="预防与避免" tabindex="-1">预防与避免 <a class="header-anchor" href="#预防与避免" aria-label="Permalink to &quot;预防与避免&quot;">​</a></h1><div class="epigraph"><p>预防在设计时拆掉 Coffman 四条件之一；避免在运行时拒绝走进不安全状态——银行家是后者，锁排序是前者。</p><footer>—— 据 Coffman, Elphick and Shoshani, 1971；Silberschatz et al. 对死锁处理策略的整理</footer></div><p><a href="/cs/deadlock-coffman">上一课</a>给出互斥、占有并等待、不可抢占、循环等待。缺口是把对策分成两档：<strong>预防</strong>（静态拆掉一条，使环不可能）与<strong>避免</strong>（动态，每次分配检查安全序列）。检测并恢复是第三档，本课点名，银行家算法细节下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>四条同时才可能死锁。预防：允许抢占资源（锁很难真抢）、禁止占有并等待（一次申请全部、或拿不到就放光已持有的）、或破坏循环等待（全系统锁序）。避免：进程先报最大需求，系统只进入仍存在安全序列的状态。缺口不是再举 AB-BA 例子，而是<strong>何时用静态纪律、何时用运行时检查</strong>。</p><p><span class="marginnote">检测：允许进可能死锁的状态，用资源分配图找环，再杀进程或抢资源。Unix 用户锁多半既不避免也不检测，靠预防式排序。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选一条破：内核文档里的锁层级（稍后 lock-ordering 课展开）破循环等待；申请文件锁时非阻塞失败则回滚，破占有并等待。避免留给种类少、配额已知的资源。本课不把矩阵算法写完。</p>',8)),(e(),s(p,null,{default:r(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20FOUR%5B%22%E5%9B%9B%E6%9D%A1%E4%BB%B6%22%5D%20--%3E%20PREV%5B%22%E9%A2%84%E9%98%B2%3A%20%E6%B0%B8%E4%B9%85%E6%8B%86%E6%8E%89%E4%B8%80%E6%9D%A1%22%5D%0A%20%20FOUR%20--%3E%20AV%5B%22%E9%81%BF%E5%85%8D%3A%20%E5%8F%AA%E5%81%9C%E7%95%99%E5%9C%A8%E5%AE%89%E5%85%A8%E6%80%81%22%5D%0A%20%20FOUR%20--%3E%20DET%5B%22%E6%A3%80%E6%B5%8B%3A%20%E6%89%BE%E7%8E%AF%E5%86%8D%E6%81%A2%E5%A4%8D%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/cs/priority-inversion">优先级反转</a>：反转无环也可发生，不是本课对象。活锁也不是环。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>预防把正确性放到编码规范：违反锁序即可能死锁，锁依赖检测器抓动态违反。避免更灵活但要配额，通用 <code>malloc</code> 几乎给不出诚实的最大需求——所以<a href="/cs/banker-algorithm">银行家</a> 是教材算法，不是 Linux 页框分配器。检测有滞后与误杀。三档都比「假装不会死锁」贵，贵在不同地方。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把分布式死锁探针写完。可消耗资源（信号量 V）与可重用锁的图论不同，主干仍以可重用锁为准。银行家的安全序列下一课专写。</p><p>后课默认：预防靠破条件，避免靠安全态。安全序列如何检查，下一课银行家算法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>预防：设计时去掉四条件之一；避免：运行时不进不安全态。</li><li>检测是第三档；通用 OS 对用户内存很少跑银行家。</li><li>安全序列算法是下一课。</li><li>出处：Coffman et al., 1971；Silberschatz et al., <em>OSC</em>。</li></ul>',8))])}const b=l(h,[["render",E]]);export{k as __pageData,b as default};
